namespace ghidra.feature.vt.gui.task;



using ghidra.feature.vt.api.main;
using ghidra.feature.vt.api.main;
using ghidra.program.model.address;
using ghidra.util.task;

public class SetMarkupItemDestinationAddressTask : VtTask {

	protected List<VTMarkupItem> markupItems;
	protected Address destinationAddress;

	public SetMarkupItemDestinationAddressTask(VTSession session, List<VTMarkupItem> markupItems,
			Address destinationAddress) : this("Set Markup Item Destination Address", session, markupItems, destinationAddress)
    {
	}

	protected SetMarkupItemDestinationAddressTask(string title, VTSession session,
			List<VTMarkupItem> markupItems, Address destinationAddress) : base(title, session)
    {
		this.markupItems = markupItems;

		this.destinationAddress = destinationAddress;
	}

	/* @Override */
	protected bool doWork(TaskMonitor monitor)
    {
		monitor.initialize(markupItems.size());

		foreach (VTMarkupItem markupItem in markupItems) {
			monitor.checkCancelled();
			markupItem.setDestinationAddress(destinationAddress);
			monitor.incrementProgress(1);
		}
		return true;
	}
}
